<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/health_network_v590.php';$u=hn590_require_login('/health-network-account.php');$uid=(int)$u['id'];$orders=[];$bookings=[];$reports=[];$requests=[];try{$q=db()->prepare('SELECT o.*,p.name pharmacy_name FROM health_pharmacy_orders_v590 o LEFT JOIN health_pharmacies_v590 p ON p.id=o.pharmacy_id WHERE o.tenant_id=? AND o.user_id=? ORDER BY o.created_at DESC LIMIT 40');$q->execute([hn590_tid(),$uid]);$orders=$q->fetchAll()?:[];}catch(Throwable $e){}try{$q=db()->prepare('SELECT b.*,l.name lab_name,t.name test_name FROM health_lab_bookings_v590 b LEFT JOIN health_labs_v590 l ON l.id=b.lab_id LEFT JOIN health_lab_tests_v590 t ON t.id=b.test_id WHERE b.tenant_id=? AND b.user_id=? ORDER BY b.created_at DESC LIMIT 40');$q->execute([hn590_tid(),$uid]);$bookings=$q->fetchAll()?:[];}catch(Throwable $e){}try{$q=db()->prepare('SELECT r.*,b.booking_no,t.name test_name,l.name lab_name FROM health_lab_reports_v590 r JOIN health_lab_bookings_v590 b ON b.id=r.booking_id LEFT JOIN health_lab_tests_v590 t ON t.id=b.test_id LEFT JOIN health_labs_v590 l ON l.id=b.lab_id WHERE r.tenant_id=? AND b.user_id=? AND r.status=\'published\' ORDER BY r.uploaded_at DESC');$q->execute([hn590_tid(),$uid]);$reports=$q->fetchAll()?:[];}catch(Throwable $e){}try{$q=db()->prepare('SELECT r.*,a.vehicle_no FROM health_ambulance_requests_v590 r LEFT JOIN health_ambulances_v590 a ON a.id=r.ambulance_id WHERE r.tenant_id=? AND r.user_id=? ORDER BY r.created_at DESC LIMIT 40');$q->execute([hn590_tid(),$uid]);$requests=$q->fetchAll()?:[];}catch(Throwable $e){}hn590_track('my_health_network');hn590_public_header('My Health Network','Your connected healthcare service history.');
?><main><section class="hn590-account-hero"><div class="hn590-shell"><span>MY HEALTH NETWORK</span><h1>Welcome, <?=e($u['name']??'Member')?></h1><p>Your service history across connected ShahkotPK healthcare modules.</p><div class="hn590-actions"><a class="hn590-btn" href="/my-health.php">Doctor Appointments</a><a class="hn590-btn" href="/my-blood.php">Blood Bank</a><a class="hn590-btn" href="/labs.php">Book Lab</a></div></div></section><section class="hn590-section"><div class="hn590-shell hn590-account-grid"><section><div class="hn590-head"><div><span>PHARMACY</span><h2>Orders</h2></div></div><div class="hn590-tablewrap"><table><thead><tr><th>Order</th><th>Pharmacy</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><?=e($o['order_no'])?></td><td><?=e($o['pharmacy_name']?:'Pharmacy')?></td><td><?=hn590_money((float)$o['total_amount'])?></td><td><span class="hn590-status"><?=e($o['status'])?></span></td></tr><?php endforeach;?><?php if(!$orders):?><tr><td colspan="4">No pharmacy orders yet.</td></tr><?php endif;?></tbody></table></div></section><section><div class="hn590-head"><div><span>LABS</span><h2>Bookings & reports</h2></div></div><div class="hn590-tablewrap"><table><thead><tr><th>Booking</th><th>Test</th><th>Date</th><th>Status</th></tr></thead><tbody><?php foreach($bookings as $b):?><tr><td><?=e($b['booking_no'])?></td><td><?=e($b['test_name']?:'Test')?><small><?=e($b['lab_name']?:'Lab')?></small></td><td><?=e(date('d M Y H:i',strtotime($b['scheduled_at'])))?></td><td><span class="hn590-status"><?=e($b['status'])?></span></td></tr><?php endforeach;?><?php if(!$bookings):?><tr><td colspan="4">No lab bookings yet.</td></tr><?php endif;?></tbody></table></div><div class="hn590-reports"><?php foreach($reports as $r):?><a href="/health-report.php?id=<?=(int)$r['id']?>"><i>▤</i><span><b><?=e($r['test_name']?:'Lab Report')?></b><small><?=e($r['lab_name']?:'Lab')?> · <?=e(date('d M Y',strtotime($r['uploaded_at'])))?></small></span><em>Open</em></a><?php endforeach;?></div></section><section class="span2"><div class="hn590-head"><div><span>AMBULANCE</span><h2>Dispatch requests</h2></div><a href="/ambulance.php">New Request →</a></div><div class="hn590-request-timeline"><?php foreach($requests as $r):?><div><i></i><span><b><?=e($r['request_no'])?> · <?=e($r['status'])?></b><small><?=e($r['pickup_address'])?> → <?=e($r['destination']?:'Destination not set')?><?=($r['vehicle_no']?' · Vehicle '.e($r['vehicle_no']):'')?></small></span><em><?=e(date('d M H:i',strtotime($r['created_at'])))?></em></div><?php endforeach;?><?php if(!$requests):?><div class="hn590-empty">No ambulance requests yet.</div><?php endif;?></div></section></div></section></main><?php hn590_public_footer();?>
